export async function isOrgArchived(orgId: OrgId): Promise<boolean> {
  const row = getDb()
    .select({ archivedAt: organizations.archivedAt })
    .from(organizations)
    .where(eq(organizations.id, orgId))
    .get();
  return row !== undefined && row.archivedAt !== null;
}

/**
 * Every live org the user still holds a live membership in. A closed org
 * drops out of every member's list at once.
 */
export async function listOrgsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  const rows = getDb()
    .select({ org: organizations })
    .from(members)
    .innerJoin(organizations, eq(organizations.id, members.orgId))
    .where(
      and(
        eq(members.userId, userId),
        isNull(members.archivedAt),
        isNull(organizations.archivedAt),
      ),
    )
    .all();

  return rows.map((row) => toOrganization(row.org));
}

