 * Closes the org. Only a live row matches, so two closes racing each other
 * cannot both succeed: the loser finds nothing to update.
 */
export async function archiveOrg(
  orgId: OrgId,
  now: Date = new Date(),
): Promise<Organization> {
  const row = getDb()
    .update(organizations)
    .set(archivePatch(now))
    .where(and(eq(organizations.id, orgId), isNull(organizations.archivedAt)))
    .returning()
    .get();

  if (!row) throw new AlreadyArchivedError("Organization", orgId);
  return toOrganization(row);
}

