/**
 * Closing an organization is a soft delete guarded by a typed confirmation,
 * the same shape GitHub uses: the caller has to retype the slug. It is final
 * and immediate: the org is archived and its subscription ends in the same
 * instant, so no trial expiry or plan change can follow it. Closing an org
 * that is already closed is a conflict.
 */
export async function deleteOrganization(
  actor: Actor,
  input: DeleteOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:delete", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  assertNotArchived("Organization", org.id, org);

  if (org.slug !== input.confirmSlug) {
    throw new Error("The confirmation does not match this organization's slug");
  }

  const closedAt = new Date();
  const closed = await orgRepo.archiveOrg(input.orgId, closedAt);
  await subscriptionRepo.endSubscription(input.orgId, toIsoTimestamp(closedAt));

  return closed;
}

