import * as webhookRepo from "@/server/repositories/webhook-repository";
import { runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import { runTrialExpiryJob } from "@/server/jobs/trial-expiry-job";
import { runWebhookDeliveryJob } from "@/server/jobs/webhook-delivery-job";
import * as invitationService from "@/server/services/invitation-service";
import * as issueService from "@/server/services/issue-service";
import * as notificationService from "@/server/services/notification-service";
import * as orgService from "@/server/services/organization-service";
import * as sessionService from "@/server/services/session-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";
import type { OrgId, IsoTimestamp, UserId } from "@/types/common";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];
const NOW = new Date("2026-06-01T07:00:00.000Z");
const LATER = new Date("2026-08-01T07:00:00.000Z");

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  while (detachers.length > 0) detachers.pop()?.();
  cleanup();
});

function count(type: Parameters<typeof subscribe>[0]): () => number {
  let n = 0;
  detachers.push(subscribe(type, () => { n += 1; }));
  return () => n;
}

describe("closing a workspace", () => {
  it("closes once, ends the subscription, and refuses a second close as a conflict", async () => {
    const tenant = await createTenant("closeone", "growth");
    const planChanges = count("billing.plan_changed");

    const closed = await orgService.deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });
    expect(closed.archivedAt).not.toBeNull();

    const sub = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(sub?.status).toBe("canceled");
    expect(sub?.cancelAt).not.toBeNull();

    await expect(
      orgService.deleteOrganization(tenant.actors.owner, {
        orgId: tenant.org.id,
        confirmSlug: tenant.org.slug,
      }),
    ).rejects.toMatchObject({ code: "conflict" });
    expect(planChanges()).toBe(0);
  });

  it("a wrong confirmation refuses without closing anything", async () => {
    const tenant = await createTenant("closewrong", "growth");

    await expect(
      orgService.deleteOrganization(tenant.actors.owner, {
        orgId: tenant.org.id,
        confirmSlug: "not-the-slug",
      }),
    ).rejects.toThrow(/confirmation/);

    const org = await orgRepo.findOrgById(tenant.org.id);
    expect(org?.archivedAt).toBeNull();
  });

  it("disappears from lists and cannot be entered or switched into, but other shared workspaces are unaffected", async () => {
    const tenant = await createTenant("closelist", "growth");
    const other = await createTenant("closelistother", "growth");
    await memberRepo.insertMember(other.org.id, tenant.userIds.member, "member", null);

    const member = tenant.userIds.member;
    const principal = {
      userId: member,
      email: "member@closelist.test",
      activeOrgId: tenant.org.id,
      expiresAt: "2099-01-01T00:00:00.000Z" as IsoTimestamp,
    };

    const before = await orgService.listOrganizationsForUser(member);
    expect(before.map((o) => o.id)).toContain(tenant.org.id);

    await orgService.deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });

    const after = await orgService.listOrganizationsForUser(member);
    expect(after.map((o) => o.id)).not.toContain(tenant.org.id);
    expect(after.map((o) => o.id)).toContain(other.org.id);

    await expect(
      sessionService.resolveActorForOrg(principal, tenant.org.slug),
    ).resolves.toBeNull();
    await expect(
      sessionService.resolveActorForOrg(principal, tenant.org.slug, { includeArchived: true }),
    ).resolves.not.toBeNull();
    await expect(
      sessionService.switchActiveOrg(principal, { orgId: tenant.org.id }),
    ).rejects.toThrow();
    await expect(
      sessionService.resolveActorForOrg(
        { ...principal, activeOrgId: other.org.id },
        other.org.slug,
      ),
    ).resolves.not.toBeNull();
  });

  it("refuses to accept an invitation sent before the closing and emits nothing", async () => {
    const tenant = await createTenant("closeinvite", "growth");
    const token = "closeinvite-token-0123456789-abcdefghijk";
    await invitationRepo.insertInvitation(
      tenant.org.id,
      { orgId: tenant.org.id, email: "late@closeinvite.test", role: "member", expiresInDays: 14 },
      tenant.userIds.owner,
      hashToken(token),
    );
    const joined = count("member.joined");

    await orgService.deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });

    const newcomer = await userRepo.insertUser({
      email: "newcomer@closeinvite.test",
      name: "Newcomer",
      passwordHash: "seed",
    });

    await expect(
      invitationService.acceptInvitation(newcomer.id, { token }),
    ).rejects.toThrow();
    expect(await memberRepo.findMember(tenant.org.id, newcomer.id)).toBeNull();
    expect(joined()).toBe(0);
  });

  it("produces no overdue reminders and no notifications", async () => {
    const tenant = await createTenant("closeod", "growth");
    await usageRepo.recomputeUsage(tenant.org.id);
    const number = await (await import("@/server/repositories/issue-repository")).nextIssueNumber(
      tenant.org.id,
      tenant.project.id,
    );
    const issueRepo = await import("@/server/repositories/issue-repository");
    await issueRepo.insertIssue(
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Late",
        assigneeId: tenant.userIds.member,
        dueAt: "2026-01-01T00:00:00.000Z",
      }),
      tenant.userIds.owner,
      number,
    );

    const overdue = count("issue.overdue");
    await runOverdueIssueJob(NOW);
    expect(overdue()).toBeGreaterThan(0);

    await orgService.deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });

    const seen = count("issue.overdue");
    await runOverdueIssueJob(LATER);
    expect(seen()).toBe(0);

    const rows = await notificationService.notify(
      tenant.org.id,
      "issue_overdue",
      [tenant.userIds.member],
      { title: "x", body: "y", href: "/z", actorId: null },
    );
    expect(rows).toEqual([]);
  });

  it("fails queued webhook deliveries instead of sending them", async () => {
    const tenant = await createTenant("closehook", "growth");
    const endpoint = await webhookRepo.insertEndpoint(
      { orgId: tenant.org.id, url: "https://example.com/hook", eventTypes: ["issue.created"] },
      "secret-closehook",
    );
    const delivery = await webhookRepo.enqueueDelivery(
      tenant.org.id,
      endpoint.id,
      "issue.created",
      "{}",
    );

    await orgService.deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });

    const result = await runWebhookDeliveryJob(LATER);
    expect(result.processed).toBe(0);

    const row = getDb()
      .select()
      .from(webhookDeliveries)
      .where(eq(webhookDeliveries.id, delivery.id))
      .get();
    expect(row?.status).toBe("failed");
    expect(row?.deliveredAt).toBeNull();
  });

  it("records no plan change when a trial would otherwise expire", async () => {
    const tenant = await createTenant("closetrial", "growth");
    await orgService.deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });
    // Put the row back into "trialing" to prove the job itself refuses a closed org.
    getDb()
      .update(subscriptions)
      .set({ status: "trialing" })
      .where(eq(subscriptions.orgId, tenant.org.id))
      .run();

    const planChanges = count("billing.plan_changed");
    const result = await runTrialExpiryJob(LATER);
    expect(result.processed).toBe(0);
    expect(planChanges()).toBe(0);

    const sub = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(sub?.plan).toBe("growth");
  });

  it("search reindex skips a closed workspace", async () => {
    const tenant = await createTenant("closeidx", "growth");
    const before = await runSearchReindexJob(tenant.org.id);
    expect(before.processed).toBeGreaterThan(0);

    await orgService.deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });

    const after = await runSearchReindexJob(tenant.org.id);
    expect(after.processed).toBe(0);
  });

  it("keeps a closed workspace's address reserved", async () => {
    const tenant = await createTenant("closeslug", "growth");
    await orgService.deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });

    const owner = tenant.userIds.owner as UserId;
    const created = await orgService.createOrganization(owner, {
      name: "Closeslug",
      slug: "closeslug",
      plan: "free",
    });
    expect(created.slug).not.toBe("closeslug");
    expect(created.slug.startsWith("closeslug")).toBe(true);
  });
});

