import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

const cookieState = { token: "" };
vi.mock("next/headers", () => ({
  cookies: async () => ({
    get: (name: string) => (name === "taskflow_session" ? { value: cookieState.token } : undefined),
    set: () => undefined,
    delete: () => undefined,
  }),
}));
vi.mock("next/cache", () => ({
  revalidateTag: () => undefined,
  revalidatePath: () => undefined,
}));

import { hashToken } from "@/lib/hash";
import * as sessionRepo from "@/server/repositories/session-repository";
import { deleteOrganizationAction } from "@/actions/organizations/delete-organization";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { IsoTimestamp } from "@/types/common";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

async function signIn(userId: Parameters<typeof sessionRepo.createSession>[0], activeOrgId: string) {
  const token = `scratch-session-${Math.random().toString(36).slice(2)}-padding-padding`;
  cookieState.token = token;
  await sessionRepo.createSession(
    userId,
    hashToken(token),
    "2099-01-01T00:00:00.000Z" as IsoTimestamp,
  );
  void activeOrgId;
}

describe("danger-zone delete action", () => {
  it("closes on the first submit and reports a conflict on a stale repeat", async () => {
    const tenant = await createTenant("actclose", "growth");
    await signIn(tenant.userIds.owner, tenant.org.id);

    const first = await deleteOrganizationAction({
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });
    console.log("FIRST_RESULT", JSON.stringify(first));
    expect(first.ok).toBe(true);

    const second = await deleteOrganizationAction({
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });
    expect(second.ok).toBe(false);
    if (!second.ok) expect(second.error.code).toBe("conflict");
  });

  it("refuses a closed workspace to other actions via the normal path", async () => {
    const tenant = await createTenant("actlock", "growth");
    await signIn(tenant.userIds.owner, tenant.org.id);
    await deleteOrganizationAction({ orgId: tenant.org.id, confirmSlug: tenant.org.slug });

    const { requireActorFor } = await import("@/lib/actor");
    await expect(requireActorFor(tenant.org.id)).rejects.toThrow();
  });
});

